#include <iostream>
#include <vector>

int main() {
    std::vector<int> v = {5, 10, 15};
    v.push_back(20);
    v.push_back(25);

    int sum = 0;
    for (int value : v) {
        sum += value;
    }
    std::cout << "size: " << v.size() << std::endl;
    std::cout << "sum: " << sum << std::endl;

