}

#include <iostream>
#include <string>
#include <vector>

struct Student {
    std::string name;
    int course;
    double grade;
};

int main() {
    std::vector<Student> group = {
        {"Anna", 1, 4.5},
        {"Boris", 1, 3.8}
    };

    Student best = group[0];
    if (group[1].grade > best.grade) {
        best = group[1];
    }
    std::cout << "Best: " << best.name << std::endl;

    double sum = group[0].grade + group[1].grade;
    std::cout << "Avg: " << sum / group.size() << std::endl;
    return 0;
}

#include <iostream>

void swap(int& a, int& b) {
    int tmp = a;
    a = b;
    b = tmp;
}

int main() {
    double x = 3.14;
    double* p = &x;
    double& r = x;
    r = 2.71;
    std::cout << x << ' ' << *p << std::endl;

    int a = 1, b = 2;
    swap(a, b);
    std::cout << a << ' ' << b << std::endl;
    return 0;
}

