              << std::get<2>(record) << std::endl;
    return 0;
}

#include <iostream>
#include <string>
#include <utility>

// Two results out of one function: no out-parameters needed
std::pair<int, int> quotientRemainder(int a, int b) {
    return {a / b, a % b};
}

int main() {
    auto [q, r] = quotientRemainder(17, 5);
    std::cout << "17 / 5: " << q << " and " << r << std::endl;

    std::pair<std::string, int> person = {"Alex", 19};
    const auto& [name, age] = person;
    std::cout << name << " is " << age << std::endl;
    return 0;
}

#include <iostream>

int main() {
    int table[2][3] = {
        {1, 2, 3},
        {4, 5, 6}
    };

    int rows = sizeof(table) / sizeof(table[0]);
    int cols = sizeof(table[0]) / sizeof(table[0][0]);
    int total = 0;

    for (int i = 0; i < rows; i++) {
        int rowSum = 0;
        for (int j = 0; j < cols; j++) {
            rowSum += table[i][j];
        }
        total += rowSum;
        std::cout << "Row " << i << ": " << rowSum << std::endl;
    }
    std::cout << "Total: " << total << std::endl;
    return 0;
}

#include <iostream>
#include <queue>
#include <stack>
#include <string>

int main() {
    std::stack<int> s;
    s.push(1);
    s.push(2);
    s.push(3);

    std::cout << "stack pops:";
    while (!s.empty()) {
        std::cout << ' ' << s.top();
        s.pop();
    }
    std::cout << std::endl;

    std::queue<std::string> q;
    q.push("first");
    q.push("second");
    q.push("third");

    std::cout << "queue pops:";
    while (!q.empty()) {
        std::cout << ' ' << q.front();
        q.pop();
    }
    std::cout << std::endl;
    return 0;
}
